// Animated demo clips and how-to text from the open-source "free-exercise-db-with-videos" project.
// TRIAL, limited to the owner's list of core gym exercises (chest, back, shoulders, legs, arms, abs). Everything else,
// including band, yoga and Pilates exercises, uses YouTube. Code and text are MIT licensed; the videos are described as an
// animated set redistributed with the maintainer's rights, so reuse rights should be confirmed before launch.
// Set SHOW_ANIMATED_DEMOS to false to go back to YouTube only. YouTube videos are never removed.

export const SHOW_ANIMATED_DEMOS = true

/**
 * Only OFFER strength exercises that have an animation when building a program (yoga and Pilates are not affected, they
 * use YouTube). Set to false to offer the whole library again. Saved programs keep their exercises either way.
 */
export const ANIMATED_ONLY_STRENGTH = true

/**
 * Show an Animation / Real person switch in the Demo window. It appears for exercises that have both an animation and a saved
 * YouTube video (src/lib/exerciseVideos.ts); the animation shows first. Set to false to show animations only.
 */
export const YOUTUBE_NEXT_TO_ANIMATION = true

export interface AnimatedDemo {
  male?: string
  female?: string
  thumb?: string
  steps: string[]
  cues: string[]
  mistakes: string[]
  breathing: string
}

