  "Band Bent-Over Rear Lateral Raise": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-bent-over-rear-lateral-raise.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-bent-over-rear-lateral-raise.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-bent-over-rear-lateral-raise.jpg", "steps": ["Stand on a resistance band, feet shoulder-width apart.", "Hinge forward at hips, keeping back flat.", "Hold band with both hands, arms hanging down.", "Raise arms out to sides until parallel with shoulders.", "Lower arms back down with control."], "cues": ["Flat back", "Slight elbow bend", "Squeeze shoulders", "Slow control"], "mistakes": ["Rounding back", "Shrugging shoulders", "Using momentum"], "breathing": "Exhale during the raise, inhale during the lowering."},
  "Band Hip Abduction": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-hip-abduction.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-hip-abduction.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-hip-abduction.jpg", "steps": ["Place a resistance band around your thighs or ankles.", "Stand tall with feet hip-width apart.", "Shift weight to one leg.", "Lift the other leg laterally against band resistance.", "Return leg to start; repeat on both sides."], "cues": ["Keep chest up", "Stable standing leg", "Move slowly", "Feel glute engagement"], "mistakes": ["Leaning torso", "Poor balance", "Letting band snap back"], "breathing": "Exhale as you lift leg, inhale as you return."},
  "Band Hip Adduction": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-hip-adduction.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-hip-adduction.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-hip-adduction.jpg", "steps": ["Secure a resistance band to a sturdy anchor at ankle height.", "Loop the other end around your working ankle.", "Stand tall and hold onto a support if needed.", "Bring your working leg across your body, adducting at the hip.", "Slowly return to the starting position and repeat."], "cues": ["Keep core tight", "Move with control", "Avoid swinging", "Maintain upright posture"], "mistakes": ["Using momentum", "Rotating hips outward", "Bending the standing leg excessively"], "breathing": "Exhale as you pull leg inward, inhale as you return."},
  "Band One Arm Front Raise": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-one-arm-forward-raise.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-one-arm-forward-raise.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-one-arm-forward-raise.jpg", "steps": ["Stand with one foot on the band for resistance.", "Hold handle in one hand at thigh level, palm facing down.", "Keep arm straight, raise it forward to shoulder height.", "Pause briefly at the top.", "Lower arm back down slowly and repeat."], "cues": ["Raise to shoulder height", "Keep elbow soft", "Don't swing", "Control the descent"], "mistakes": ["Swinging the arm", "Bending at the elbow", "Raising above shoulder"], "breathing": "Exhale as you lift, inhale as you lower."},
  "Band One-Leg Kickback (Bent Position)": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-one-leg-kickback-bent-position.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-one-leg-kickback-bent-position.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-one-leg-kickback-bent-position.jpg", "steps": ["Anchor the band and loop it around your working ankle.", "Start on all fours with hands under shoulders and knees bent.", "Engage your core and extend one leg backward against band resistance.", "Pause and squeeze the glute at the top.", "Return to starting position and repeat for desired reps, then switch legs."], "cues": ["Keep back flat", "Drive heel upward", "Squeeze glutes", "Avoid arching lower back"], "mistakes": ["Sagging the lower back", "Rotating the hips", "Using momentum"], "breathing": "Exhale as you kick back, inhale as you bring the knee in."},
  "Band Resisted Decline Sit-Up": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-decline-sit-ups.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-decline-sit-ups.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-decline-sit-ups.jpg", "steps": ["Attach a resistance band securely behind the decline bench.", "Lie on the bench with your feet anchored, holding the band at the chest or behind the neck.", "Engage your core and perform a sit-up, raising your torso towards your knees.", "Control the movement back down to starting position.", "Repeat for the desired repetitions."], "cues": ["Keep tension in band", "Crunch up slowly", "Avoid swinging", "Exhale on exertion"], "mistakes": ["Using momentum", "Letting band go slack", "Improper anchoring of feet"], "breathing": "Exhale as you sit up, inhale as you lower down."},
