  "Band Seated Row": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-seated-row.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-seated-row.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-seated-row.jpg", "steps": ["Sit on the floor with legs straight and loop the band over your feet.", "Grab the band handles or ends with both hands, arms extended.", "Keep back straight and chest up.", "Pull the handles back, driving elbows past your torso and squeezing shoulder blades.", "Release slowly to the starting position."], "cues": ["Lead with elbows", "Keep chest up", "Squeeze shoulder blades", "Don't round your back"], "mistakes": ["Rounding the back", "Using momentum", "Letting band slack between reps"], "breathing": "Exhale as you row, inhale as you return to start."},
  "Band Side Bend": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-side-bend.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-side-bend.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-side-bend.jpg", "steps": ["Anchor the resistance band securely at ground level.", "Stand beside the anchor point, feet shoulder-width apart.", "Hold the band handle with the outside hand, arm extended alongside your body.", "Keeping your torso straight, bend sideways at the waist away from the anchor.", "Return to the starting position and repeat for reps, then switch sides."], "cues": ["Keep chest up", "Don’t rotate hips", "Bend directly to the side", "Controlled return"], "mistakes": ["Rotating the torso instead of bending laterally", "Bending forward or backward", "Letting the band snap back", "Using momentum"], "breathing": "Exhale while bending, inhale on the return."},
  "Band Standing Calf Raise": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-standing-calf-raise.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-standing-calf-raise.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-standing-calf-raise.jpg", "steps": ["Stand with feet shoulder-width on the band.", "Hold band handles by sides or at shoulders for resistance.", "Keep torso upright and brace core.", "Raise heels to stand on the balls of your feet, contracting calves.", "Lower heels back to the floor slowly."], "cues": ["Go all the way up", "Pause at the top", "Lower slowly", "Keep core engaged"], "mistakes": ["Partial reps", "Letting heels drop too quickly", "Leaning forward or backward"], "breathing": "Exhale as you rise, inhale as you lower."},
  "Band Standing Crunch": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-standing-crunch.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-standing-crunch.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-standing-crunch.jpg", "steps": ["Attach the band to an anchor around waist height and stand facing away from it.", "Hold the band at your chest with both hands and step forward until the band is taut.", "Set your feet about hip-width apart and soften your knees.", "Brace your midsection and curl your ribs down, bending your torso forward.", "Pause briefly at the bottom while keeping your hips mostly still.", "Slowly uncurl your torso and return to an upright position under control."], "cues": ["Ribs down", "Curl through your spine", "Keep hips still", "Move slowly both ways"], "mistakes": ["Pulling the band with the arms instead of curling the torso.", "Hinging at the hips like a bow instead of rounding into a crunch.", "Letting the band snap the torso back upright.", "Standing too close to the anchor so the band has no tension."], "breathing": "Exhale as you crunch forward, and inhale as you return to standing."},
