  "Bench Pull-Up": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/bench-pull-ups.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/bench-pull-ups.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/bench-pull-ups.jpg", "steps": ["Place a bench under a pull-up bar.", "Grip the bar with hands wider than shoulder-width.", "Position feet on the bench for support.", "Pull your chest towards the bar, using feet as needed.", "Lower yourself slowly to starting position."], "cues": ["Keep core engaged", "Lead with chest", "Pull elbows down and back", "Don't let legs push too much"], "mistakes": ["Using too much leg drive", "Swinging body or kicking feet", "Chin barely reaching bar", "Not controlling descent"], "breathing": "Exhale as you pull up, inhale as you lower down."},
