  "Cable Close Grip Lat Pulldown": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-close-grip-front-lat-pulldown.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/cable-close-grip-front-lat-pulldown.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/cable-close-grip-front-lat-pulldown.jpg", "steps": ["Attach a V-bar or close grip handle to the cable machine.", "Sit down and secure your thighs under the pads.", "Grasp the handle with a neutral grip, hands parallel.", "Pull the handle down to the top of your chest, keeping torso vertical.", "Slowly return the handle to the top without locking elbows."], "cues": ["Lead with the elbows", "Keep chest up", "Do not swing back", "Squeeze lats at bottom"], "mistakes": ["Leaning back excessively", "Using momentum", "Not fully engaging lats", "Rounding shoulders forward"], "breathing": "Exhale as you pull down, inhale as you return up."},
  "Cable Crossover Reverse Fly": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-crossover-reverse-fly.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/cable-crossover-reverse-fly.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/cable-crossover-reverse-fly.jpg", "steps": ["Set both cable handles to the low pulleys and stand centered between them.", "Grab the left handle in your right hand and the right handle in your left hand, then step forward to create tension.", "Hinge forward slightly with a soft bend in your knees and keep your chest up and back flat.", "Start with your arms angled down and crossed in front of you, elbows slightly bent.", "Pull both arms out and back in a wide arc until your hands reach about shoulder height.", "Squeeze your rear shoulders and upper back at the end position.", "Return the handles slowly to the start without shrugging or changing your torso position."], "cues": ["Lead with your elbows", "Keep a soft elbow bend", "Chest up, back flat", "Don't shrug your shoulders"], "mistakes": ["Standing fully upright and turning it into a row", "Bending and straightening the elbows during the rep", "Shrugging the shoulders up toward the ears", "Swinging the torso to move the handles"], "breathing": "Inhale as you return the handles to the start, and exhale as you pull your arms out and back."},
  "Cable Lying Triceps Extension": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-lying-triceps-extension.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/cable-lying-triceps-extension.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/cable-lying-triceps-extension.jpg", "steps": ["Attach a rope handle to a low cable and place a flat bench in line with the pulley.", "Lie face up on the bench with your head closest to the cable and hold the rope with a neutral grip.", "Press the rope straight above your chest with your arms fully extended.", "Keep your upper arms mostly still and bend your elbows to lower the rope toward your forehead.", "Pause briefly when your elbows are deeply bent.", "Straighten your elbows to return the rope to the start position above your chest."], "cues": ["Elbows stay tucked", "Upper arms stay still", "Move only at the elbows", "Finish with straight arms"], "mistakes": ["Letting the elbows flare wide to the sides", "Drifting the upper arms backward and turning it into a pullover", "Lowering the rope behind the head instead of toward the forehead", "Bouncing out of the bottom instead of controlling the cable"], "breathing": "Inhale as you lower the rope toward your forehead, and exhale as you straighten your elbows back to the start."},
  "Cable One Arm Curl": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-one-arm-curl.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/cable-one-arm-curl.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/cable-one-arm-curl.jpg", "steps": ["Stand beside the cable machine and hold the handle in one hand with your palm facing up.", "Step out until the cable is taut, then stand tall with your elbow tucked against your side.", "Curl the handle upward by bending your elbow without letting your upper arm drift forward.", "Raise the handle until your forearm is close to your biceps, then briefly squeeze your arm.", "Lower the handle slowly until your arm is straight again while keeping tension on the cable.", "Complete all reps on one arm, then switch sides."], "cues": ["Keep elbow pinned", "Palm stays up", "Stand tall", "Lower with control"], "mistakes": ["Elbow swings forward during the curl", "Shoulder shrugs up toward the ear", "Torso leans back to move the weight", "Handle drops quickly on the way down"], "breathing": "Exhale as you curl the handle up, and inhale as you lower it back down."},
