  "Cable One Arm Lateral Pulldown": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-one-arm-lateral-pulldown.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/cable-one-arm-lateral-pulldown.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/cable-one-arm-lateral-pulldown.jpg", "steps": ["Attach a single handle to the high cable pulley.", "Sit or stand, arm overhead grasping the handle.", "Stabilize your body and engage your core.", "Pull handle down to shoulder/upper chest level.", "Pause, then return handle slowly."], "cues": ["Pull elbow down and in", "Don’t shrug shoulders", "Keep torso upright", "Focus on the lats"], "mistakes": ["Arching back excessively", "Letting shoulder roll forward", "Using momentum"], "breathing": "Exhale while pulling down, inhale while releasing."},
  "Cable One Arm Lateral Raise": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-one-arm-lateral-raise.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/cable-one-arm-lateral-raise.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/cable-one-arm-lateral-raise.jpg", "steps": ["Stand sideways to the cable machine and grasp the handle with the outside hand.", "Step away until the cable is taut, with your arm down by your side and a slight bend in your elbow.", "Brace your torso and keep your shoulders level.", "Raise your arm out to the side until your hand reaches about shoulder height.", "Pause briefly without shrugging your shoulder.", "Lower the handle back down with control to the starting position.", "Complete the reps on one side, then switch arms."], "cues": ["Lead with the elbow", "Keep shoulders level", "Raise to shoulder height", "Lower with control"], "mistakes": ["Shrugging the working shoulder toward the ear", "Swinging the torso to start the rep", "Turning the raise into a front raise", "Lifting the hand far above shoulder height"], "breathing": "Exhale as you raise your arm to the side, and inhale as you lower it back down under control."},
