  "EZ Barbell Anti Gravity Press": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/ez-barbell-anti-gravity-press.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/ez-barbell-anti-gravity-press.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/ez-barbell-anti-gravity-press.jpg", "steps": ["Stand tall with your feet about hip- to shoulder-width apart and hold the EZ bar at shoulder height with an overhand grip.", "Brace your core and keep your wrists stacked over your elbows.", "Press the bar straight overhead until your arms are fully extended above your shoulders.", "Move your head slightly back as the bar passes your face, then bring your head through under the bar at the top.", "Lower the bar under control back to shoulder height.", "Repeat each rep from a stable standing position."], "cues": ["Press straight overhead", "Ribs down, core tight", "Wrists stacked over elbows", "Head through at top"], "mistakes": ["Leaning back hard and turning it into an incline press", "Pressing the bar out in front instead of overhead", "Flaring the elbows too far out from the start", "Lowering the bar too fast and bouncing at the shoulders"], "breathing": "Inhale and brace at shoulder height, exhale as you press overhead, and inhale again as you lower the bar back down."},
