  "Lever Back Extension": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-back-extension.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/lever-back-extension.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/lever-back-extension.jpg", "steps": ["Adjust the machine so the back pad sits comfortably against your upper back and your feet are secured on the platform.", "Sit tall against the pad and grip the handles or side bars.", "Brace your core and lean your torso forward under control through the machine's range.", "Stop at the bottom when you feel a comfortable stretch and keep your feet pressed into the platform.", "Drive your torso back against the pad until you return to an upright position.", "Repeat smoothly without bouncing or jerking the pad."], "cues": ["Brace before you move", "Move through a smooth arc", "Keep feet firmly planted", "Return to tall posture"], "mistakes": ["Using momentum and bouncing out of the bottom position", "Pushing through a short, rushed range of motion", "Letting the feet lift or shift on the platform", "Hyperextending far past upright at the top"], "breathing": "Inhale as you lean forward, then exhale as you extend back to an upright position."},
