  "Reverse Grip Machine Lat Pulldown": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/reverse-grip-machine-lat-pulldown.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/reverse-grip-machine-lat-pulldown.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/reverse-grip-machine-lat-pulldown.jpg", "steps": ["Adjust the seat so your knees fit snugly under the pads and place your feet flat on the floor.", "Reach up and grab the handles with an underhand grip about shoulder-width apart.", "Sit tall with your chest up and arms fully extended overhead.", "Pull the handles down toward your upper chest by driving your elbows down and back.", "Squeeze your upper back and lats at the bottom without leaning far backward.", "Slowly let the handles rise until your arms are straight again while keeping control."], "cues": ["Chest up", "Drive elbows down", "Keep wrists straight", "Control the return"], "mistakes": ["Leaning far back and turning it into a row", "Pulling the handles behind the neck", "Shrugging the shoulders up toward the ears", "Letting the weight slam back at the top"], "breathing": "Inhale as the handles rise back up, and exhale as you pull them down toward your chest."},
  "Reverse-Grip Cable Lat Pulldown": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-bar-lateral-pulldown-reverse-grip.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/cable-bar-lateral-pulldown-reverse-grip.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/cable-bar-lateral-pulldown-reverse-grip.jpg", "steps": ["Set the cable bar attachment and sit with knees secured under the pad.", "Grasp the bar with a reverse (supinated) shoulder-width grip.", "Lean back slightly, chest up, arms fully extended.", "Pull the bar down to your upper chest by contracting your lats.", "Slowly return the bar to the start position with control."], "cues": ["Pull elbows down", "Keep chest up", "Don’t swing the torso", "Grip the bar tightly"], "mistakes": ["Using too much momentum", "Letting shoulders round", "Leaning too far back"], "breathing": "Exhale as you pull down, inhale as you return up."},
