  "Smith Machine Deadlift": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/smith-deadlift-deadlift-1.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/smith-deadlift-deadlift-1.jpg", "steps": ["Position feet shoulder-width beneath the Smith bar.", "Grip the bar just outside your knees with both hands.", "Hinge hips back and lower torso, keeping chest up.", "Extend hips and knees to lift the bar along the guides.", "Lower the bar with control to the starting position."], "cues": ["Hinge at hips", "Keep back flat", "Drive through heels", "Bar close to shins"], "mistakes": ["Rounding the lower back", "Lifting with arms instead of legs", "Letting the bar drift away from body", "Jerky movements"], "breathing": "Inhale as you lower the bar, exhale as you lift."},
