  "Goblet Squat": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-goblet-squat.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/dumbbell-goblet-squat.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/dumbbell-goblet-squat.jpg", "steps": ["Stand tall with your feet about shoulder-width apart and hold one dumbbell vertically at your chest with both hands.", "Brace your midsection and keep your elbows pointed down close to your body.", "Sit your hips down and back while bending your knees, and lower until your thighs are parallel to the floor or slightly lower.", "Keep the dumbbell tight to your chest and your feet flat as your knees track over your toes.", "Drive through your whole foot to stand back up until your hips and knees are fully extended.", "Reset your stance and repeat the next rep."], "cues": ["Chest up", "Keep heels down", "Knees track over toes", "Hold the bell close"], "mistakes": ["Letting the dumbbell drift away from the chest", "Heels lifting off the floor at the bottom", "Knees collapsing inward during the squat", "Folding the chest forward instead of staying upright"], "breathing": "Inhale as you lower into the squat, and exhale as you stand back up."},
  "Hack Squat": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/sled-hack-squat.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/sled-hack-squat.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/sled-hack-squat.jpg", "steps": ["Stand on the sled platform with your back against the pad and your shoulders under the pads.", "Place your feet about shoulder-width apart on the platform with toes turned slightly out, then grip the handles.", "Unlock the sled and lower yourself by bending your knees and hips until your thighs reach parallel or your deepest controlled position.", "Keep your full foot planted against the platform as your knees track in line with your toes.", "Drive through your heels and midfoot to extend your knees and hips and return the sled upward.", "Stop just short of locking your knees, then continue into the next repetition."], "cues": ["Keep your back on pad", "Knees track over toes", "Push through whole foot", "Control the descent"], "mistakes": ["Feet placed too low so the heels lift off the platform", "Knees collapsing inward during the lowering phase", "Lower back rounding or hips peeling off the pad", "Bouncing out of the bottom instead of pausing briefly"], "breathing": "Inhale as you lower the sled, then exhale as you press it back up."},
  "Romanian Deadlift": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-deadlift.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/dumbbell-deadlift.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/dumbbell-deadlift.jpg", "steps": ["Stand tall with your feet hip- to shoulder-width apart, holding a dumbbell in each hand in front of your thighs.", "Brace your midsection, pull your shoulders back, and keep your arms straight.", "Push your hips back and bend your knees slightly as you slide the dumbbells down close to your legs.", "Lower until the dumbbells reach around mid-shin or just below your knees while keeping your back flat.", "Drive through your feet and push your hips forward to stand back up with the dumbbells at your thighs.", "Finish tall with your hips and knees straight, then repeat the hinge."], "cues": ["Hips back first", "Keep dumbbells close", "Chest proud", "Stand tall at top"], "mistakes": ["Rounding the lower back as the dumbbells lower", "Letting the dumbbells drift far in front of the legs", "Squatting straight down instead of hinging the hips back", "Locking the knees rigid or overbending them"], "breathing": "Inhale as you lower the dumbbells with control, and exhale as you drive through your feet to stand up."},
  "Stiff-Leg Deadlift": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-straight-leg-deadlift.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/barbell-straight-leg-deadlift.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/barbell-straight-leg-deadlift.jpg", "steps": ["Stand tall with your feet hip-width apart and hold the barbell in front of your thighs with straight arms.", "Soften your knees slightly and brace your midsection.", "Push your hips back and lower the bar down your legs while keeping your back flat and your legs nearly straight.", "Lower until the bar reaches mid-shin or until you feel a strong hamstring stretch without losing your back position.", "Drive your hips forward and stand tall, keeping the bar close to your legs the whole way up.", "Finish with your hips locked out and shoulders stacked over your hips."], "cues": ["Hips back, not down", "Keep the bar close", "Soft knees, flat back", "Stand tall and squeeze glutes"], "mistakes": ["Bending the knees into a squat as the bar lowers", "Letting the bar drift forward away from the legs", "Rounding the lower back near the bottom", "Jerking the bar off the bottom instead of lifting smoothly"], "breathing": "Inhale and brace before hinging down, then exhale as you drive your hips forward to stand up."},
  "Lying Leg Curl": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-lying-leg-curl.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/lever-lying-leg-curl.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/lever-lying-leg-curl.jpg", "steps": ["Adjust the machine so your knees line up with the machine's pivot and the pad rests against the back of your lower legs above your heels.", "Lie face down on the bench with your legs straight and grab the handles or bench edges for support.", "Press your hips into the pad and point your toes forward to set your start position.", "Curl the pad upward by bending your knees until your heels move toward your glutes.", "Pause briefly at the top while keeping your hips down and thighs on the pad.", "Lower the pad back down under control until your legs are straight again."], "cues": ["Keep hips glued down", "Curl through the hamstrings", "Move slow on the way down", "Knees stay in line"], "mistakes": ["Lifting the hips off the pad at the top", "Using momentum to swing the pad upward", "Stopping short and not fully lowering the pad", "Feet turning sharply inward or outward during the curl"], "breathing": "Exhale as you curl the pad up, and inhale as you lower it back down under control."},
