  "Wrist Curl": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-over-bench-wrist-curl.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/dumbbell-over-bench-wrist-curl.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/dumbbell-over-bench-wrist-curl.jpg", "steps": ["Sit at a bench and place your forearms on top with your palms facing up.", "Hold a dumbbell in each hand and slide forward until your wrists hang just past the bench edge.", "Let your hands lower to gently stretch your wrists at the bottom.", "Curl your wrists up by lifting your knuckles toward your forearms.", "Squeeze your forearms briefly at the top.", "Lower the dumbbells back down under control until your wrists extend again."], "cues": ["Move only your wrists", "Forearms stay glued down", "Curl through full range", "Lower slowly"], "mistakes": ["Lifting the forearms off the bench during the curl.", "Swinging the dumbbells instead of moving only the wrists.", "Using partial range and stopping before the wrists fully lower.", "Bending the elbows to help raise the weight."], "breathing": "Inhale as you lower your wrists and exhale as you curl them up."},
