  "Dumbbell Shrug": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-shrug.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/dumbbell-shrug.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/dumbbell-shrug.jpg", "steps": ["Stand tall with a dumbbell in each hand at your sides and your feet about hip-width apart.", "Let your arms hang straight with your palms facing your body.", "Lift your shoulders straight up toward your ears without bending your elbows.", "Pause briefly at the top while keeping your torso still.", "Lower your shoulders back down under control to the start position and repeat."], "cues": ["Shoulders straight up", "Arms stay long", "Neck relaxed", "Control the lowering"], "mistakes": ["Rolling the shoulders in circles instead of lifting straight up and down.", "Bending the elbows and turning the move into an upright row.", "Leaning the torso back or forward to swing the dumbbells.", "Jutting the head forward as the shoulders rise."], "breathing": "Exhale as you shrug your shoulders up, and inhale as you lower them back down."},
  "Upright Row": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-upright-row.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-upright-row.jpg", "steps": ["Stand tall with a dumbbell in each hand in front of your thighs, palms facing your body.", "Brace your midsection and keep your chest lifted.", "Pull the dumbbells straight up along the front of your body by driving your elbows up and out.", "Raise until the dumbbells reach about upper-chest height and your elbows stay higher than your hands.", "Pause briefly, then lower the dumbbells back to your thighs with control."], "cues": ["Lead with your elbows", "Keep dumbbells close", "Shoulders down and back", "Lift to upper chest"], "mistakes": ["Pulling the dumbbells all the way to the chin", "Letting the wrists bend sharply at the top", "Swinging the torso to start the lift", "Hands rising higher than the elbows"], "breathing": "Exhale as you pull the dumbbells up, and inhale as you lower them back down."},
  "Burpee": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/burpee.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/burpee.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/burpee.jpg", "steps": ["Stand tall with your feet about hip-width apart.", "Bend your knees, hinge at your hips, and place your hands on the floor in front of your feet.", "Jump both feet back to a high plank with your body in a straight line.", "Lower your chest to the floor, then press back up to plank.", "Jump both feet forward to the outside of your hands.", "Drive through your feet and jump straight up, reaching your arms overhead as you leave the floor.", "Land softly and go straight into the next rep."], "cues": ["Keep your core braced.", "Land softly under control.", "Chest up on the jump.", "Move as one straight line."], "mistakes": ["Hips sagging low in the plank or push-up.", "Feet landing too narrow under the body.", "Hands placed far in front of the shoulders.", "Landing stiff-legged with no knee bend."], "breathing": "Inhale as you drop down and move into plank, then exhale as you press up and jump."},
