  "Lying Leg Raise": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lying-floor-leg-raise.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/lying-floor-leg-raise.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/lying-floor-leg-raise.jpg", "steps": ["Lie flat on your back, legs straight.", "Keep arms at your sides or under hips.", "Lift legs upward, keeping knees straight.", "Raise legs until hips come up slightly.", "Lower legs slowly without touching the floor."], "cues": ["Engage core", "Keep lower back down", "Control descent", "Avoid swinging"], "mistakes": ["Arching lower back", "Using momentum", "Touching feet to ground between reps"], "breathing": "Exhale as you raise legs, inhale as you lower."},
  "Dumbbell Standing Calf Raise": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-standing-calf-raise.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/dumbbell-standing-calf-raise.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/dumbbell-standing-calf-raise.jpg", "steps": ["Stand upright with a dumbbell in each hand and place your feet about hip-width apart.", "Let your arms hang by your sides and keep your knees softly bent.", "Press through the balls of your feet and lift your heels as high as you can.", "Pause briefly at the top while staying tall through your torso.", "Lower your heels back to the floor with control and repeat."], "cues": ["Rise straight up", "Press through big toe", "Control the lowering", "Keep torso tall"], "mistakes": ["Bouncing at the bottom instead of lowering under control", "Rolling the ankles outward or inward", "Bending the knees to turn it into a squat", "Leaning the torso forward as the heels lift"], "breathing": "Inhale as you lower your heels, and exhale as you press up onto your toes."},
