  "Band Triceps Pushdown": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-triceps-pushdown.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-triceps-pushdown.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-triceps-pushdown.jpg", "steps": ["Anchor the band overhead and stand facing it with a handle or end in each hand.", "Bend your elbows to about 90 degrees and pin your upper arms close to your sides.", "Brace your torso and press your hands straight down until your elbows fully extend.", "Pause briefly at the bottom and squeeze your triceps.", "Slowly let the band rise back up until your forearms return to the start position.", "Repeat without letting your elbows drift forward or outward."], "cues": ["Elbows pinned to sides", "Only move the forearms", "Stand tall", "Squeeze at lockout"], "mistakes": ["Upper arms swinging forward and back", "Elbows flaring away from the torso", "Leaning body weight onto the band", "Stopping short of full elbow extension"], "breathing": "Exhale as you press the band down, and inhale as you return to the start."},
  "Band Overhead Triceps Extension": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-overhead-triceps-extension.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-overhead-triceps-extension.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-overhead-triceps-extension.jpg", "steps": ["Stand on the middle of the band with feet hip-width apart and hold one end in each hand.", "Raise your hands overhead and bend your elbows so your hands move behind your head.", "Keep your upper arms close to your ears and brace your midsection.", "Straighten your elbows to press the band overhead until your arms are fully extended.", "Pause briefly at the top, then bend your elbows slowly to return behind your head.", "Repeat without letting your elbows flare wide."], "cues": ["Elbows point forward", "Upper arms stay still", "Brace your ribs down", "Fully straighten the elbows"], "mistakes": ["Elbows flare out to the sides", "Lower back arches as the band goes overhead", "Upper arms drift forward and backward", "Only moving partway instead of fully extending"], "breathing": "Inhale as you lower your hands behind your head, and exhale as you straighten your elbows overhead."},
  "Band Pull-Through": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-pull-through.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-pull-through.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-pull-through.jpg", "steps": ["Anchor the band at floor level and loop it between your legs.", "Face away from the anchor and walk forward until the band is taut.", "Stand with feet about hip-width apart and soften your knees.", "Push your hips back and hinge forward, letting the band travel behind you.", "Lower until you feel your hamstrings stretch while keeping your back flat.", "Drive your hips forward to stand tall and squeeze your glutes at the top."], "cues": ["Push hips back", "Keep ribs down", "Stand tall at top", "Squeeze glutes hard"], "mistakes": ["Squatting down instead of hinging back", "Rounding the lower back as you fold forward", "Letting the band pull the hips backward at lockout", "Bending the knees too much and shifting into the quads"], "breathing": "Inhale as you hinge back and exhale as you drive your hips forward to stand."},
  "Band Lat Pulldown": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-kneeling-one-arm-pulldown.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-kneeling-one-arm-pulldown.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-kneeling-one-arm-pulldown.jpg", "steps": ["Anchor the band overhead and kneel facing the anchor point.", "Grab the band with one hand and extend that arm up and slightly forward.", "Brace your torso and keep your chest tall without leaning back.", "Pull your elbow down toward your side until your hand reaches about shoulder or rib level.", "Squeeze your lat at the bottom while keeping your shoulder down.", "Slowly straighten your arm back overhead under control.", "Complete all reps on one side, then switch arms."], "cues": ["Drive elbow to your side", "Keep ribs down", "Shoulder away from your ear", "Move slowly on the return"], "mistakes": ["Leaning the torso back to finish the pull", "Shrugging the shoulder up toward the ear", "Bending and straightening the wrist during the pull", "Letting the band snap the arm back overhead"], "breathing": "Inhale as your arm returns overhead, and exhale as you pull the band down to your side."},
  "Resistance Band Row": {"male": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-straight-back-seated-row.mp4", "female": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-straight-back-seated-row.mp4", "thumb": "https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-straight-back-seated-row.jpg", "steps": ["Sit on the floor and extend your legs forward.", "Loop the band around your feet securely.", "Grip the band handles with both hands, arms extended.", "Keeping your back straight, pull the handles toward your waist, elbows close to your body.", "Pause, squeeze your shoulder blades, then slowly return to the starting position."], "cues": ["Keep chest up", "Maintain neutral spine", "Squeeze shoulder blades", "Control the release"], "mistakes": ["Rounding your back", "Letting arms flare out", "Using momentum rather than back muscles"], "breathing": "Exhale as you row, inhale as you return to start."},
